# region: intake
def intake(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: digest
def digest(xs):
    return [v for v in xs if v % 2 == 0]

# region: sift
def sift(xs, factor=10):
    return [v * factor for v in xs[1:]]

# region: shape
def shape(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: render
def render(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: fold
def fold(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return fold(render(shape(sift(digest(intake(raw))))))

